import { useShallow } from 'zustand/react/shallow';
import { Button } from '@/design-system';
import { useTranslation } from '@/i18n';
import { useSessionStore } from '@/core/sync/session/useSession';
import { signInUrl } from '@/core/sync/session/sessionApi';
import { useSyncStatusStore } from '@/core/sync/status';
import { useSignOutFlow } from '@/shared/sync/useSignOutFlow';
import { useDeleteAccountFlow } from '@/shell/sync/useDeleteAccountFlow';
import { useToastStore } from '@/core/store';
import { useLibraryStore } from '@/core/store/library';

const PROVIDER_LABEL_KEY = {
  google: 'auth.providerGoogle',
  github: 'auth.providerGithub',
} as const;

export function AccountTab() {
  const t = useTranslation();

  const { status, user } = useSessionStore(useShallow((s) => ({ status: s.status, user: s.user })));
  const sync = useSyncStatusStore(
    useShallow((s) => ({
      state: s.state,
      lastSyncedAt: s.lastSyncedAt,
      pendingCount: s.pendingCount,
      lastError: s.lastError,
    }))
  );
  const layoutCount = useLibraryStore((s) => s.library.entries.length);

  const { signOut, dialog: signOutDialog } = useSignOutFlow();
  const { deleteAccount, dialog: deleteAccountDialog } = useDeleteAccountFlow();
  const addToast = useToastStore((s) => s.addToast);

  const handleDeleteAccount = async () => {
    const result = await deleteAccount();
    if (result.status === 'error') {
      addToast({
        message: t('account.deleteAccount.errorToast', { message: result.message }),
        type: 'error',
      });
    }
  };

  return (
    <div id="account" className="space-y-8">
      <section>
        <h3 className="text-base font-semibold text-content mb-3">
          {t('account.identity.heading')}
        </h3>
        {status === 'authenticated' && user ? (
          <div className="rounded-md border border-stroke-subtle p-4 space-y-1">
            <div className="text-sm text-content font-medium">{user.displayName ?? user.email}</div>
            <div className="text-xs text-content-tertiary">{user.email}</div>
            <div className="text-xs text-content-tertiary">
              {t('account.identity.signedInVia', {
                provider: t(PROVIDER_LABEL_KEY[user.provider]),
              })}
            </div>
          </div>
        ) : status === 'anonymous' ? (
          <div className="rounded-md border border-stroke-subtle p-4 space-y-4">
            <div className="space-y-1">
              <div className="text-sm text-content font-medium">
                {t('account.localMode.heading')}
              </div>
              <div className="text-xs text-content-tertiary">
                {t('account.localMode.description')}
              </div>
              <div className="text-xs text-content-tertiary">
                {layoutCount > 0
                  ? t('account.localMode.savedOnDeviceCount', { count: layoutCount })
                  : t('account.localMode.readyWhenYouAre')}
              </div>
            </div>

            <div className="space-y-2">
              <div className="text-xs text-content-secondary">
                {t('account.localMode.benefitsIntro')}
              </div>

